create or replace function private.review_summaries() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg((case when r.parent_id=auth.uid() or private.is_staff() then to_jsonb(r)-'evidence'-'feedback_id' else to_jsonb(r)-'evidence'-'feedback_id'-'parent_id'-'appointment_id' end)||jsonb_build_object('reviewer_key',encode(extensions.digest(r.parent_id::text||':'||r.specialist_id::text,'sha256'),'hex'),'case_summary',case when r.is_demo then f.public_summary else null end)),'[]') from public.reviews r left join private.review_case_features f on f.review_id=r.id where auth.uid() is not null and (r.parent_id=auth.uid() or private.is_staff() or (r.status='verified' and r.visit_verified and (not r.is_demo or private.demo_actor())));
$$;
-- A readable review body can be translated; private case features remain hidden.
alter table public.content_translations drop constraint content_translations_source_kind_check;
alter table public.content_translations add constraint content_translations_source_kind_check check(source_kind in('message','reply','team','question','answer','review'));
alter policy authorized_content_translation on public.content_translations using((source_kind='reply' and exists(select 1 from public.community_replies r where r.id=source_id)) or (source_kind='team' and exists(select 1 from public.team_recommendations r where r.id=source_id)) or (source_kind='question' and exists(select 1 from public.questions q where q.id=source_id)) or (source_kind='answer' and exists(select 1 from public.answers a where a.id=source_id)) or (source_kind='review' and exists(select 1 from public.reviews r where r.id=source_id)));
